// QueueLock corresponds to mln_queue_lock. Your lock on a Vulkan queue that you
// and the render sessions of a GPU device all submit to.
//
// A session holds the lock only while it submits or presents to the queue, or
// submits the empty batch that drains its work from the queue. It never holds
// the lock while it waits. Set both lock and unlock, or neither when you don't
// submit to the queue yourself.
//
// Don't hold the lock while you call the library.
//
// It can run on a library thread, and it can't call the library.
//
// See mln_queue_lock in the C API reference:
// https://maplibre.org/maplibre-native-ffi/reference/c/render__target_8h.html
type QueueLock struct {
	Lock   func()
	Unlock func()
	native *bindingNativeRegistration
}

// NewNativeQueueLock returns a QueueLock from C values that native code in the
// host supplies: lock, unlock, userData, and releaseUserData are the members of
// the C struct that QueueLock presents, which the binding copies unchanged. The
// first call that carries the QueueLock consumes it. Native code releases
// userData if it accepts the call, and otherwise the binding calls
// releaseUserData. A later call returns StatusInvalidState.
func NewNativeQueueLock(lock, unlock, userData, releaseUserData uintptr) QueueLock {
	return QueueLock{native: bindingNewNativeRegistration(userData, releaseUserData, lock, unlock)}
}

func nativeQueueLock(input QueueLock, arena *bindingArena) C.mln_queue_lock {
	raw := C.mln_queue_lock{}
	if input.native != nil {
		registration := arena.native(input.native)
		if input.Lock != nil || input.Unlock != nil {
			arena.fail("QueueLock carries both a native registration and a func")
		}
		raw.lock = C.mln_queue_lock_callback(C.binding_address(C.uintptr_t(registration.callbacks[0])))
		raw.unlock = C.mln_queue_lock_callback(C.binding_address(C.uintptr_t(registration.callbacks[1])))
		raw.user_data = C.binding_address(C.uintptr_t(registration.userData))
		raw.release_user_data = C.mln_user_data_release(C.binding_address(C.uintptr_t(registration.release)))
	} else if input.Lock != nil || input.Unlock != nil {
		raw.user_data = arena.register(input)
		raw.release_user_data = C.mln_user_data_release(C.binding_release)
		if input.Lock != nil {
			raw.lock = C.mln_queue_lock_callback(C.binding_mln_queue_lock_lock)
		}
		if input.Unlock != nil {
			raw.unlock = C.mln_queue_lock_callback(C.binding_mln_queue_lock_unlock)
		}
	}
	return raw
}

