// Abandon stops the session right away, without running its pending graphics
// work.
//
// Use it when the target's graphics objects are going away and a detach can't
// finish first. Pending work completes with StatusTargetLost, and pending frame
// demands finish with RenderResultTargetNotReady. Once the call returns, the
// library no longer uses your graphics objects, and you can attach another
// session to the map. Release the session afterward.
//
// Abandon keeps the session's OpenGL and WebGPU objects until the process
// exits, and reports how many it kept. Detach the session instead to free them.
//
// A session lets go of your graphics objects later when you call this on the
// thread that runs its graphics work: from a callback that the session runs
// there, once the callback returns, and for a session driven by
// RenderDriverKindCallerGraphicsThread, at your next
// RenderSessionHandle.ServiceDriverWork() for it.
//
// See mln_render_session_abandon in the C API reference:
// https://maplibre.org/maplibre-native-ffi/reference/c/render__session_8h.html
func (receiver *RenderSessionHandle) Abandon() (RenderAbandonResult, error) {
	var outResult C.mln_render_abandon_result
	outResult.size = C.uint32_t(unsafe.Sizeof(outResult))
	return bindingGet(bindingOwned(receiver.owner()), func(arena *bindingArena, raw uint64, diagnostic *C.mln_diagnostic) int32 {
		return int32(C.mln_render_session_abandon(C.mln_render_session(raw), &outResult, diagnostic))
	}, func(arena *bindingArena) RenderAbandonResult {
		return copyRenderAbandonResult(outResult)
	})
}

// AcquireFrame takes the newest rendered frame from the session's texture ring,
// if one is ready.
//
// Older frames that you haven't acquired are dropped, and the session can
// render over a frame before you acquire it. While you hold a frame in every
// texture of the ring, new frames wait until you release one. When no frame is
// ready, it succeeds and writes the null handle.
//
// See mln_render_session_acquire_frame in the C API reference:
// https://maplibre.org/maplibre-native-ffi/reference/c/render__session_8h.html
//
// Errors:
//   - StatusUnsupported when the session lacks
//     RenderSessionCapabilityFlagFrameAcquisition.
//   - StatusTargetLost or StatusNativeError, as
//     RenderSessionSnapshot.FailureStatus reports, when the session has failed.
//   - StatusInvalidState when you detached, abandoned, released, or disposed
//     the session.
func (receiver *RenderSessionHandle) AcquireFrame() (*AcquiredFrameHandle, error) {
	var outFrame C.mln_acquired_frame
	return bindingGet(bindingOwned(receiver.owner()), func(arena *bindingArena, raw uint64, diagnostic *C.mln_diagnostic) int32 {
		return int32(C.mln_render_session_acquire_frame(C.mln_render_session(raw), &outFrame, diagnostic))
	}, func(arena *bindingArena) *AcquiredFrameHandle {
		if outFrame == 0 {
			return nil
		}
		adopted := adoptAcquiredFrameHandle(uint64(outFrame), receiver)
		return adopted
	})
}

