// NewRuntime creates a runtime.
//
// A runtime holds maps and the resource loading, cache, and offline regions
// that they share.
//
// In a browser, the library runs on the thread that loaded its module and never
// blocks it: commands, render sessions, completions, wakes and callbacks all
// run on that thread, in tasks of the library's own after the call that started
// them returns. Wait for a completion with a callback, or yield to the event
// loop; a blocking wait can't end. Load the module on a dedicated Web Worker,
// so that the map's work doesn't delay the page. On the page's thread it works
// too, but every frame and style parse runs there.
//
// See mln_runtime_create in the C API reference:
// https://maplibre.org/maplibre-native-ffi/reference/c/runtime_8h.html
//
// Errors:
//   - StatusInvalidArgument when the cache database file that options names
//     can't be opened or created.
//   - StatusUnsupported in a browser for a cache path: the browser caches the
//     runtime's requests.
func NewRuntime(options *RuntimeOptions) (*RuntimeHandle, error) {
	var outRuntime C.mln_runtime
	return bindingGet(bindingGlobal(), func(arena *bindingArena, raw uint64, diagnostic *C.mln_diagnostic) int32 {
		return int32(C.mln_runtime_create(bindingStoreOptional(options, arena, nativeRuntimeOptions), &outRuntime, diagnostic))
	}, func(arena *bindingArena) *RuntimeHandle {
		adopted := adoptRuntimeHandle(uint64(outRuntime), nil)
		return adopted
	})
}

// CreateMap creates a map on runtime.
//
// Asynchronous calls on the map before the completion runs wait for it, and
// complete with StatusInvalidState when creation fails.
//
// See mln_runtime_create_map in the C API reference:
// https://maplibre.org/maplibre-native-ffi/reference/c/map_8h.html
//
// Errors:
//   - StatusInvalidArgument when the fallback_font_faces of options isn't an
//     array of font files.
func (receiver *RuntimeHandle) CreateMap(options MapOptions) (mapHandle *MapHandle, ready *Future[struct{}], err error) {
	var outMap C.mln_map
	result, err := bindingStartWith(bindingOwned(receiver.owner()), func(arena *bindingArena, raw uint64, completion *C.mln_completion, diagnostic *C.mln_diagnostic) int32 {
		return int32(C.mln_runtime_create_map(C.mln_runtime(raw), bindingStore(nativeMapOptions(options, arena), arena), &outMap, completion, diagnostic))
	}, completionUnit, func(arena *bindingArena, future *Future[struct{}]) struct {
		mapHandle *MapHandle
		ready     *Future[struct{}]
	} {
		adopted := adoptMapHandle(uint64(outMap), receiver)
		return struct {
			mapHandle *MapHandle
			ready     *Future[struct{}]
		}{adopted, future}
	})
	return result.mapHandle, result.ready, err
}

